import csv,collections,math,functools
r=list(csv.DictReader(open('responses.csv')))
d=collections.defaultdict(list)
for x in r: d[x['number_set']].append((int(x['target']),int(x['rating'])))
for s,v in d.items():
  ex=[int(a) for a in s.split(',')]; g=functools.reduce(math.gcd,ex)
  if len(ex)>1 and g>=2:
    agg=collections.defaultdict(list)
    for t,y in v: agg[t].append(y)
    print(s,g,' '.join(f'{t}:{sum(y)/len(y):.1f}' for t,y in sorted(agg.items())))
